import java.util.*;

public class Main {
    public static void main(String[] args) {
        List<String> list = new ArrayList<>();
        list.add("A");
        list.add("B");
        list.add("C");

        // 1. Iterator Pattern
        Iterator<String> it = list.iterator();
        while(it.hasNext()) {
            String s = it.next();
            if (s.equals("B")) {
                it.remove(); // Safe Removal
                // list.remove("B"); // Fail-Fast Error!
            }
        }

        System.out.println(list);
    }
}
